/**
 * Computes the factorial of a non-negative integer.
 * Returns a BigInt so large results stay exact.
 *
 * @param {number|bigint} n - A non-negative integer.
 * @returns {bigint} n!
 * @throws {TypeError|RangeError} If n is not a non-negative integer.
 */
function factorial(n) {
  if (typeof n === "bigint") {
    if (n < 0n) throw new RangeError("n must be non-negative");
  } else {
    if (!Number.isInteger(n)) throw new TypeError("n must be an integer");
    if (n < 0) throw new RangeError("n must be non-negative");
    n = BigInt(n);
  }

  let result = 1n;
  for (let i = 2n; i <= n; i++) {
    result *= i;
  }
  return result;
}

// Examples
