 * Computes the factorial of a non-negative integer.
 * @param {number|bigint} n - A non-negative integer.
 * @returns {bigint} n! as a BigInt.
 * @throws {TypeError} If n is not an integer.
 * @throws {RangeError} If n is negative.
 */
function factorial(n) {
  if (typeof n === "bigint") {
    if (n < 0n) throw new RangeError("n must be non-negative");
  } else {
    if (!Number.isInteger(n)) throw new TypeError("n must be an integer");
    if (n < 0) throw new RangeError("n must be non-negative");
    n = BigInt(n);
  }

  let result = 1n;
  for (let i = 2n; i <= n; i++) {
    result *= i;
  }
  return result;
}

// Examples
console.log(factorial(0));   // 1n
console.log(factorial(5));   // 120n
console.log(factorial(20));  // 2432902008176640000n
console.log(factorial(25));  // 15511210043330985984000000n
console.log(factorial(5).toString()); // "120"
```

**How it works**
- Validates that the input is a non-negative integer.
- Starts with `result = 1n`, which also handles `0! = 1`.
- Multiplies together all integers from 2 to `n`.

**Simpler version (regular numbers)**

If you don't need huge values, this version returns a normal number. It's accurate up to `18!` exactly, and it returns `Infinity` above `170!`:

```javascript
function factorialNumber(n) {
  if (!Number.isInteger(n) || n < 0) {
    throw new RangeError("n must be a non-negative integer");
  }
  let result = 1;
  for (let i = 2; i <= n; i++) result *= i;
  return result;
}

console.log(factorialNumber(5)); // 120
```

