Here is an iterative JavaScript function to compute the factorial of a non-negative integer:

```javascript
function factorial(n) {
  if (!Number.isInteger(n) || n < 0) {
    throw new RangeError("Input must be a non-negative integer.");
  }

  let result = 1;
  for (let i = 2; i <= n; i++) {
    result *= i;
  }

  return result;
}

// Examples:
console.log(factorial(0)); // 1
console.log(factorial(5)); // 120
console.log(factorial(10)); // 3628800
```

### Note on Large Numbers
Standard JavaScript numbers lose precision above `21!` and overflow to `Infinity` at `171!`. If you need exact results for large integers, use `BigInt`:

```javascript
function factorialBigInt(n) {
  if (!Number.isInteger(n) || n < 0) {
    throw new RangeError("Input must be a non-negative integer.");
  }

  let result = 1n;
  for (let i = 2n; i <= BigInt(n); i++) {
    result *= i;
  }

  return result;
}

console.log(factorialBigInt(25)); // 15511210043330985984000000n
```

