/**
 * Fetch a URL and return the parsed JSON body.
 *
 * @param {string} url            The URL to request.
 * @param {RequestInit} [options] Optional fetch options (method, headers, body, signal...).
 * @returns {Promise<any>}        The parsed JSON.
 * @throws {Error}                On network failure, non-2xx status, or invalid JSON.
 */
async function fetchJson(url, options = {}) {
  const response = await fetch(url, options);

  if (!response.ok) {
    throw new Error(
      `Request to ${url} failed: ${response.status} ${response.statusText}`
    );
  }

  // Read as text first so we can give a better error for empty/invalid bodies.
  const text = await response.text();

  if (text.trim() === '') {
    return null; // empty body -> no JSON
  }

  try {
    return JSON.parse(text);
  } catch (err) {
    throw new Error(`Invalid JSON received from ${url}: ${err.message}`);
  }
}
```

