## More robust version

```js
/**
 * Fetch a URL and parse the response as JSON.
 *
 * @param {string} url
 * @param {RequestInit} [options]  - standard fetch options (method, headers, body, signal, ...)
 * @param {object}  [config]
 * @param {number}  [config.timeout=10000] - abort after N ms
 * @param {boolean} [config.strictContentType=true] - require a JSON-ish content-type
 * @returns {Promise<any>}
 */
async function fetchJson(url, options = {}, config = {}) {
  const {
    timeout = 10_000,
    strictContentType = true,
  } = config;

  // Combine the caller's signal with our timeout signal
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(new Error(`Timeout after ${timeout}ms`)), timeout);

  const onExternalAbort = () => controller.abort(options.signal?.reason);
  if (options.signal) {
    if (options.signal.aborted) onExternalAbort();
    else options.signal.addEventListener('abort', onExternalAbort, { once: true });
  }

  try {
    const response = await fetch(url, { ...options, signal: controller.signal });

    if (!response.ok) {
      // Try to surface a useful server-side error message
      const body = await response.text().catch(() => '');
      throw new Error(
        `HTTP ${response.status} ${response.statusText} for ${url}` +
        (body ? `: ${body.slice(0, 500)}` : '')
      );
    }

    const contentType = response.headers.get('content-type') || '';
    if (strictContentType && !/^application\/(?:[\w.+-]+\+)?json\b/i.test(contentType)) {
      throw new Error(`Expected JSON but got "${contentType}" from ${url}`);
    }

    // Handle 204 No Content / empty bodies gracefully
    if (response.status === 204) return null;

    const text = await response.text();
    if (!text) return null;

    try {
      return JSON.parse(text);
    } catch {
      throw new Error(`Response from ${url} is not valid JSON`);
    }
  } finally {
    clearTimeout(timer);
    options.signal?.removeEventListener('abort', onExternalAbort);
  }
}
```

## Notes

- **`response.json()` rejects on invalid JSON**, so if you want a friendlier error, read `response.text()` and `JSON.parse` it yourself (as above).
- **Check `response.ok`** — `fetch` does *not* reject on 4xx/5xx; it only rejects on network failures. This is the most common gotcha.
- **Timeouts**: `fetch` has no built-in timeout, so use `AbortController` (or `AbortSignal.timeout(ms)` in modern browsers/Node 18+, which is much shorter):

  ```js
  const res = await fetch(url, { signal: AbortSignal.timeout(5000) });
  ```

- **Node.js**: available globally since Node 18. For older versions, install `node-fetch` (v3+ is ESM-only).
- **CORS**: in a browser, cross-origin requests require the server to send appropriate `Access-Control-Allow-*` headers.
- **Retry**: for transient failures, wrap in a retry loop with exponential backoff rather than duplicating the fetch logic.

